     */
    modifier onlyVault() {
        BaseStrategyStorage.BaseStrategyStorage storage baseStrategyStorage = BaseStrategyStorage.fetch();
        if (msg.sender != baseStrategyStorage.vault) revert UnauthorizedVault();
        _;
    }

